-- Exact debit/return observations. No automatic chargeback,fee expense,
-- tax treatment,customer credit restoration or dispute-hold release.
CREATE TABLE public.checkout_dispute_balance_inspections(
 academy_id uuid NOT NULL,id uuid NOT NULL,start_id uuid NOT NULL,dispute_inspection_id uuid NOT NULL,dispute_id text NOT NULL,worker_id uuid NOT NULL,request_sha256 text NOT NULL CHECK(request_sha256~'^[a-f0-9]{64}$'),
 balance_inspection jsonb NOT NULL CHECK(jsonb_typeof(balance_inspection)='object' AND octet_length(balance_inspection::text)<=65536),object_conflict boolean NOT NULL,origin_transaction xid8 NOT NULL DEFAULT pg_current_xact_id(),recorded_by name NOT NULL DEFAULT session_user,received_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(academy_id,id),FOREIGN KEY(academy_id,start_id) REFERENCES public.payment_checkout_dispatch_starts(academy_id,id),FOREIGN KEY(academy_id,dispute_inspection_id) REFERENCES public.checkout_dispute_inspections(academy_id,id)
);
CREATE INDEX checkout_dispute_balance_history ON public.checkout_dispute_balance_inspections(academy_id,start_id,id);
CREATE TABLE public.checkout_dispute_balance_bindings(
 academy_id uuid NOT NULL,account_id text NOT NULL,livemode boolean NOT NULL,transaction_id text NOT NULL,start_id uuid NOT NULL,dispute_id text NOT NULL,amount numeric NOT NULL,currency text NOT NULL,
 PRIMARY KEY(academy_id,account_id,livemode,transaction_id),FOREIGN KEY(academy_id,start_id) REFERENCES public.payment_checkout_dispatch_starts(academy_id,id)
);
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['checkout_dispute_balance_inspections','checkout_dispute_balance_bindings'] LOOP
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY tenant_boundary ON public.%I USING(academy_id=nullif(current_setting(''app.academy_id'',true),'''')::uuid) WITH CHECK(academy_id=nullif(current_setting(''app.academy_id'',true),'''')::uuid)',t);
 EXECUTE format('CREATE POLICY checkout_result_executor ON public.%I TO kavosh_checkout_result_policy USING(true) WITH CHECK(true)',t);
 EXECUTE format('GRANT SELECT,INSERT ON public.%I TO kavosh_checkout_result_policy',t);EXECUTE format('GRANT SELECT ON public.%I TO kavosh_runtime',t);
END LOOP;END $$;
GRANT CREATE ON SCHEMA public TO kavosh_checkout_result_policy;
CREATE FUNCTION public.record_checkout_dispute_balance_inspection(p_academy uuid,p_id uuid,p_start uuid,p_page uuid,p_worker uuid,p_hash text,p_balance jsonb) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE original record;existing record;draft jsonb;j jsonb:=p_balance;r jsonb;d jsonb;keys text[];field text;total numeric:=0;complete boolean:=true;fx boolean;matched boolean;binding text;recognized boolean;manual boolean;conflict boolean;scale integer;BEGIN
 IF p_academy IS NULL OR p_id IS NULL OR p_start IS NULL OR p_page IS NULL OR p_worker IS NULL OR p_hash IS NULL OR p_hash!~'^[a-f0-9]{64}$' OR j IS NULL OR jsonb_typeof(j)<>'object' OR octet_length(j::text)>65536 THEN RAISE EXCEPTION 'INVALID_DISPUTE_BALANCE_INSPECTION' USING ERRCODE='23514';END IF;
 SELECT * INTO original FROM public.checkout_dispute_inspections WHERE academy_id=p_academy AND id=p_page AND start_id=p_start AND request_sha256=p_hash;
 SELECT a.draft INTO draft FROM public.payment_checkout_dispatch_starts s JOIN public.payment_checkout_attempts a ON a.academy_id=s.academy_id AND a.id=s.attempt_id WHERE s.academy_id=p_academy AND s.id=p_start AND a.request_sha256=p_hash;
 IF original.id IS NULL OR draft IS NULL THEN RETURN 'unavailable';END IF;
 SELECT value INTO r FROM jsonb_array_elements(original.dispute_inspection->'disputes') WHERE value->>'id'=j->>'disputeId';
 IF r IS NULL OR original.dispute_inspection->>'state' IS DISTINCT FROM 'dispute_page' OR j->>'state' IS DISTINCT FROM 'dispute_balance'
 OR j->'sessionId' IS DISTINCT FROM original.dispute_inspection->'sessionId' OR j->'paymentId' IS DISTINCT FROM original.dispute_inspection->'paymentId' OR j->'chargeId' IS DISTINCT FROM original.dispute_inspection->'chargeId'
 OR j->'disputeStatus' IS DISTINCT FROM r->'status' OR j->'disputeAmount' IS DISTINCT FROM r->'amount' OR j->'disputeCurrency' IS DISTINCT FROM r->'currency' OR j->'disputeCreatedAt' IS DISTINCT FROM r->'createdAt' OR j->'originalBalanceTransactionIds' IS DISTINCT FROM r->'balanceTransactionIds'
 OR j->>'balanceTransactionId' IS NULL OR NOT(r->'balanceTransactionIds' ? (j->>'balanceTransactionId')) THEN RAISE EXCEPTION 'DISPUTE_BALANCE_ORIGINAL_SOURCE_REQUIRED' USING ERRCODE='23514';END IF;
 FOREACH field IN ARRAY ARRAY['bankSettled','ledgerAdjusted','creditRestored','fundsReturnVerified','taxVerified'] LOOP IF j->field IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'DISPUTE_BALANCE_NOT_ACCOUNTING_AUTHORITY' USING ERRCODE='23514';END IF;END LOOP;
 keys=ARRAY['state','sessionId','paymentId','chargeId','disputeId','disputeStatus','disputeAmount','disputeCurrency','disputeCreatedAt','originalBalanceTransactionIds','balanceTransactionId','balanceType','transactionType','reportingCategory','source','providerUnitScale','grossAmount','currency','feeAmount','netAmount','createdAt','availableOn','status','exchangeRate','feeDetails','feeBreakdownComplete','requiresFxReview','disputeAmountMatched','sourceBinding','recognizedDisputeAdjustment','grossDirection','netDirection','requiresManualReview','bankSettled','ledgerAdjusted','creditRestored','fundsReturnVerified','taxVerified'];
 IF NOT(j?&keys) OR j-keys<>'{}'::jsonb THEN RAISE EXCEPTION 'DISPUTE_BALANCE_FIELDS_INVALID' USING ERRCODE='23514';END IF;
 FOREACH field IN ARRAY ARRAY['grossAmount','feeAmount','netAmount'] LOOP IF jsonb_typeof(j->field) IS DISTINCT FROM 'number' OR(j->>field)!~'^-?(0|[1-9][0-9]{0,11})$' THEN RAISE EXCEPTION 'DISPUTE_BALANCE_MONEY_INVALID' USING ERRCODE='23514';END IF;END LOOP;
 IF(j->>'netAmount')::numeric<>(j->>'grossAmount')::numeric-(j->>'feeAmount')::numeric OR j->>'currency' IS NULL OR(j->>'currency')!~'^[a-z]{3}$' OR j->>'transactionType' IS NULL OR(j->>'transactionType')!~'^[a-z][a-z0-9_]{0,63}$' OR j->>'reportingCategory' IS NULL OR(j->>'reportingCategory')!~'^[a-z][a-z0-9_]{0,63}$' OR j->>'status' IS NULL OR j->>'status' NOT IN('pending','available') THEN RAISE EXCEPTION 'DISPUTE_BALANCE_MONEY_INVALID' USING ERRCODE='23514';END IF;
 FOREACH field IN ARRAY ARRAY['createdAt','availableOn'] LOOP IF jsonb_typeof(j->field) IS DISTINCT FROM 'number' OR(j->>field)!~'^[1-9][0-9]{0,9}$' OR(j->>field)::numeric>9999999999 THEN RAISE EXCEPTION 'DISPUTE_BALANCE_DATE_INVALID' USING ERRCODE='23514';END IF;END LOOP;
 IF jsonb_typeof(j->'source') NOT IN('string','null') OR(j->'source'<>'null'::jsonb AND(j->>'source')!~'^[A-Za-z][A-Za-z0-9_]{1,220}$') OR jsonb_typeof(j->'balanceType') NOT IN('string','null') OR(j->'balanceType'<>'null'::jsonb AND(j->>'balanceType')!~'^[a-z][a-z0-9_]{0,63}$') OR jsonb_typeof(j->'exchangeRate') NOT IN('number','null') OR(j->'exchangeRate'<>'null'::jsonb AND(length(j->>'exchangeRate')>40 OR(j->>'exchangeRate')::numeric<=0)) THEN RAISE EXCEPTION 'DISPUTE_BALANCE_SOURCE_INVALID' USING ERRCODE='23514';END IF;
 scale=CASE public.checkout_provider_amount(upper(j->>'currency'),0,1) WHEN 1 THEN 0 WHEN 100 THEN 2 WHEN 1000 THEN 3 ELSE -1 END;IF j->'providerUnitScale' IS DISTINCT FROM to_jsonb(scale) THEN RAISE EXCEPTION 'DISPUTE_BALANCE_SCALE_INVALID' USING ERRCODE='23514';END IF;
 IF jsonb_typeof(j->'feeDetails') IS DISTINCT FROM 'array' OR jsonb_array_length(j->'feeDetails')>100 THEN RAISE EXCEPTION 'DISPUTE_BALANCE_FEES_INVALID' USING ERRCODE='23514';END IF;
 FOR d IN SELECT value FROM jsonb_array_elements(j->'feeDetails') LOOP
  IF jsonb_typeof(d) IS DISTINCT FROM 'object' OR d-ARRAY['amount','currency','type','application']<>'{}'::jsonb OR NOT(d?&ARRAY['amount','currency','type']) OR jsonb_typeof(d->'amount') IS DISTINCT FROM 'number' OR(d->>'amount')!~'^-?(0|[1-9][0-9]{0,11})$' OR d->>'currency' IS NULL OR(d->>'currency')!~'^[a-z]{3}$' OR d->>'type' IS NULL OR(d->>'type')!~'^[a-z][a-z0-9_]{0,63}$' OR(d?'application' AND(jsonb_typeof(d->'application') NOT IN('string','null') OR(d->'application'<>'null'::jsonb AND(d->>'application')!~'^[A-Za-z0-9_]{1,200}$'))) THEN RAISE EXCEPTION 'DISPUTE_BALANCE_FEES_INVALID' USING ERRCODE='23514';END IF;
  total=total+(d->>'amount')::numeric;complete=complete AND d->>'currency'=j->>'currency';
 END LOOP;complete=complete AND total=(j->>'feeAmount')::numeric;fx=j->>'currency'<>r->>'currency';matched=NOT fx AND abs((j->>'grossAmount')::numeric)=(r->>'amount')::numeric;
 binding=CASE WHEN j->>'source'=r->>'id' THEN 'dispute' WHEN j->>'source'=original.dispute_inspection->>'chargeId' THEN 'charge' WHEN j->'source'='null'::jsonb THEN 'pointer' ELSE 'mismatch' END;
 recognized=j->>'transactionType'='adjustment' AND binding='dispute' AND(j->>'reportingCategory'='dispute' AND(j->>'grossAmount')::numeric<0 OR j->>'reportingCategory'='dispute_reversal' AND(j->>'grossAmount')::numeric>0);manual=fx OR NOT matched OR binding<>'dispute' OR NOT recognized OR NOT complete OR(j->>'feeAmount')::numeric<>0 OR j->'balanceType' IS DISTINCT FROM '"payments"'::jsonb OR(j->>'createdAt')::numeric<(r->>'createdAt')::numeric;
 IF j->'feeBreakdownComplete' IS DISTINCT FROM to_jsonb(complete) OR j->'requiresFxReview' IS DISTINCT FROM to_jsonb(fx) OR j->'disputeAmountMatched' IS DISTINCT FROM to_jsonb(matched) OR j->'sourceBinding' IS DISTINCT FROM to_jsonb(binding) OR j->'recognizedDisputeAdjustment' IS DISTINCT FROM to_jsonb(recognized) OR j->'requiresManualReview' IS DISTINCT FROM to_jsonb(manual)
 OR j->>'grossDirection' IS DISTINCT FROM(CASE WHEN(j->>'grossAmount')::numeric<0 THEN 'debit' WHEN(j->>'grossAmount')::numeric>0 THEN 'credit' ELSE 'zero' END) OR j->>'netDirection' IS DISTINCT FROM(CASE WHEN(j->>'netAmount')::numeric<0 THEN 'debit' WHEN(j->>'netAmount')::numeric>0 THEN 'credit' ELSE 'zero' END) THEN RAISE EXCEPTION 'DISPUTE_BALANCE_REVIEW_FLAGS_INVALID' USING ERRCODE='23514';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_academy::text||':checkout-provider:'||(draft->>'accountId'),0));
 SELECT * INTO existing FROM public.checkout_dispute_balance_inspections WHERE academy_id=p_academy AND id=p_id;IF FOUND THEN IF existing.start_id=p_start AND existing.dispute_inspection_id=p_page AND existing.request_sha256=p_hash AND existing.balance_inspection=j THEN RETURN CASE WHEN existing.object_conflict THEN 'duplicate_conflict' ELSE 'duplicate' END;END IF;RAISE EXCEPTION 'DISPUTE_BALANCE_ID_CONFLICT' USING ERRCODE='23514';END IF;
 INSERT INTO public.checkout_balance_object_bindings(academy_id,account_id,livemode,transaction_id,start_id,charge_id) VALUES(p_academy,draft->>'accountId',(draft->>'livemode')::boolean,j->>'balanceTransactionId',p_start,j->>'chargeId') ON CONFLICT DO NOTHING;
 INSERT INTO public.checkout_dispute_balance_bindings(academy_id,account_id,livemode,transaction_id,start_id,dispute_id,amount,currency) VALUES(p_academy,draft->>'accountId',(draft->>'livemode')::boolean,j->>'balanceTransactionId',p_start,r->>'id',(j->>'grossAmount')::numeric,j->>'currency') ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM public.checkout_balance_object_bindings WHERE academy_id=p_academy AND account_id=draft->>'accountId' AND livemode=(draft->>'livemode')::boolean AND transaction_id=j->>'balanceTransactionId') OR NOT EXISTS(SELECT 1 FROM public.checkout_dispute_balance_bindings WHERE academy_id=p_academy AND account_id=draft->>'accountId' AND livemode=(draft->>'livemode')::boolean AND transaction_id=j->>'balanceTransactionId') THEN RAISE EXCEPTION 'DISPUTE_BALANCE_BINDING_REQUIRED' USING ERRCODE='55000';END IF;
 conflict=original.object_conflict OR binding='mismatch'
 OR NOT EXISTS(SELECT 1 FROM public.checkout_balance_object_bindings WHERE academy_id=p_academy AND account_id=draft->>'accountId' AND livemode=(draft->>'livemode')::boolean AND transaction_id=j->>'balanceTransactionId' AND start_id=p_start AND charge_id=j->>'chargeId')
 OR NOT EXISTS(SELECT 1 FROM public.checkout_dispute_balance_bindings WHERE academy_id=p_academy AND account_id=draft->>'accountId' AND livemode=(draft->>'livemode')::boolean AND transaction_id=j->>'balanceTransactionId' AND start_id=p_start AND dispute_id=r->>'id' AND amount=(j->>'grossAmount')::numeric AND currency=j->>'currency')
 OR EXISTS(SELECT 1 FROM public.checkout_refund_return_bindings WHERE academy_id=p_academy AND account_id=draft->>'accountId' AND livemode=(draft->>'livemode')::boolean AND transaction_id=j->>'balanceTransactionId')
 OR EXISTS(SELECT 1 FROM public.checkout_fee_inspections fee JOIN public.checkout_balance_object_bindings owner ON owner.academy_id=fee.academy_id AND owner.start_id=fee.start_id AND owner.transaction_id=fee.fee_inspection->>'balanceTransactionId' WHERE fee.academy_id=p_academy AND owner.account_id=draft->>'accountId' AND owner.livemode=(draft->>'livemode')::boolean AND owner.transaction_id=j->>'balanceTransactionId');
 INSERT INTO public.checkout_dispute_balance_inspections(academy_id,id,start_id,dispute_inspection_id,dispute_id,worker_id,request_sha256,balance_inspection,object_conflict) VALUES(p_academy,p_id,p_start,p_page,r->>'id',p_worker,p_hash,j,conflict);
 -- The originating retained page already creates its persistent dispute hold.
 -- Never clear it for a positive adjustment or a won/closed dispute status.
 IF NOT EXISTS(SELECT 1 FROM public.checkout_dispute_attention WHERE academy_id=p_academy AND start_id=p_start AND charge_id=j->>'chargeId') THEN RAISE EXCEPTION 'DISPUTE_BALANCE_ATTENTION_REQUIRED' USING ERRCODE='55000';END IF;
 IF conflict THEN
  INSERT INTO public.checkout_dispute_attention(academy_id,start_id,charge_id,inspection_id)
  SELECT p_academy,b.start_id,b.charge_id,p_page FROM public.checkout_balance_object_bindings b WHERE b.academy_id=p_academy AND b.account_id=draft->>'accountId' AND b.livemode=(draft->>'livemode')::boolean AND b.transaction_id=j->>'balanceTransactionId' ON CONFLICT DO NOTHING;
  IF EXISTS(SELECT 1 FROM public.checkout_balance_object_bindings b WHERE b.academy_id=p_academy AND b.account_id=draft->>'accountId' AND b.livemode=(draft->>'livemode')::boolean AND b.transaction_id=j->>'balanceTransactionId' AND NOT EXISTS(SELECT 1 FROM public.checkout_dispute_attention a WHERE a.academy_id=b.academy_id AND a.start_id=b.start_id AND a.charge_id=b.charge_id)) THEN RAISE EXCEPTION 'DISPUTE_BALANCE_OWNER_HOLD_REQUIRED' USING ERRCODE='55000';END IF;
 END IF;
 INSERT INTO public.outbox_events(academy_id,id,event_type,entity_id,request_id) VALUES(p_academy,gen_random_uuid(),CASE WHEN conflict THEN 'checkout.dispute_balance.object_conflict.critical' ELSE 'checkout.dispute_balance.observed.critical' END,p_start,p_id);
 RETURN CASE WHEN conflict THEN 'recorded_conflict' ELSE 'recorded' END;
END $$;
ALTER FUNCTION public.record_checkout_dispute_balance_inspection(uuid,uuid,uuid,uuid,uuid,text,jsonb) OWNER TO kavosh_checkout_result_policy;REVOKE CREATE ON SCHEMA public FROM kavosh_checkout_result_policy;
REVOKE ALL ON FUNCTION public.record_checkout_dispute_balance_inspection(uuid,uuid,uuid,uuid,uuid,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_checkout_dispute_balance_inspection(uuid,uuid,uuid,uuid,uuid,text,jsonb) TO kavosh_checkout_result_worker;
GRANT SELECT(academy_id,id,start_id,balance_inspection,object_conflict,origin_transaction) ON public.checkout_dispute_balance_inspections TO kavosh_event_policy;
DO $$ DECLARE d text;needle text;BEGIN
 d=pg_get_functiondef('public.checkout_notice_basis(uuid,xid8)'::regprocedure);needle='IF o.event_type LIKE ''checkout.provider.%'' THEN';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'DISPUTE_BALANCE_NOTICE_BASE_CHANGED';END IF;
 EXECUTE replace(d,needle,$branch$IF o.event_type LIKE 'checkout.dispute_balance.%' THEN
  SELECT id,balance_inspection,object_conflict INTO r FROM public.checkout_dispute_balance_inspections WHERE academy_id=tenant AND start_id=s.id AND id=o.request_id AND origin_transaction=p_origin;
  IF r.id IS NULL THEN RETURN NULL;END IF;j=r.balance_inspection;conflict=r.object_conflict;phase='dispute_balance';state=j->>'state';expected=CASE WHEN conflict THEN 'checkout.dispute_balance.object_conflict.critical' ELSE 'checkout.dispute_balance.observed.critical' END;key='dispute_balance:'||r.id::text;
 ELSIF o.event_type LIKE 'checkout.provider.%' THEN$branch$);
 d=pg_get_functiondef('public.checkout_notice_effect_required()'::regprocedure);needle='WHEN ''checkout_provider_inspections'' THEN';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'DISPUTE_BALANCE_EFFECT_BASE_CHANGED';END IF;EXECUTE replace(d,needle,'WHEN ''checkout_dispute_balance_inspections'' THEN key=''dispute_balance:''||NEW.id::text;'||E'\n '||needle);
 d=pg_get_functiondef('public.record_checkout_fee_inspection(uuid,uuid,uuid,uuid,uuid,text,jsonb)'::regprocedure);needle='conflict:=original.object_conflict';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'DISPUTE_BALANCE_FEE_BASE_CHANGED';END IF;EXECUTE replace(d,needle,needle||' OR EXISTS(SELECT 1 FROM public.checkout_dispute_balance_bindings WHERE academy_id=p_academy AND account_id=draft->>''accountId'' AND livemode=(draft->>''livemode'')::boolean AND transaction_id=j->>''balanceTransactionId'')');
 d=pg_get_functiondef('public.record_checkout_refund_return_inspection(uuid,uuid,uuid,uuid,uuid,text,jsonb)'::regprocedure);needle='conflict=original.object_conflict';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'DISPUTE_BALANCE_RETURN_BASE_CHANGED';END IF;EXECUTE replace(d,needle,needle||' OR EXISTS(SELECT 1 FROM public.checkout_dispute_balance_bindings WHERE academy_id=p_academy AND account_id=draft->>''accountId'' AND livemode=(draft->>''livemode'')::boolean AND transaction_id=j->>''balanceTransactionId'')');
END $$;
DROP TRIGGER checkout_notice_capture ON public.outbox_events;
CREATE TRIGGER checkout_notice_capture AFTER INSERT ON public.outbox_events FOR EACH ROW WHEN(NEW.event_type IN('checkout.transport.received','checkout.transport.actor_conflict.critical','checkout.transport.conflict.critical','checkout.provider.object_conflict.critical','checkout.provider.review.critical','checkout.provider.observed','checkout.fees.object_conflict.critical','checkout.fees.observed','checkout.refunds.review_required.critical','checkout.refunds.observed','checkout.refund_return.observed.critical','checkout.refund_return.object_conflict.critical','checkout.disputes.review_required.critical','checkout.disputes.observed','checkout.dispute_balance.observed.critical','checkout.dispute_balance.object_conflict.critical')) EXECUTE FUNCTION public.capture_checkout_notice();
CREATE CONSTRAINT TRIGGER checkout_notice_effect AFTER INSERT ON public.checkout_dispute_balance_inspections DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.checkout_notice_effect_required();
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 329 $$;
